1	<?php
2	
3	namespace App\Services\Stripe;
4	
5	use App\Jobs\Stripe\ExecuteCommissionPayoutJob;
6	use App\Models\Commerce\Order;
7	use App\Models\Core\Professional\Professional;
8	use App\Models\Retail\BrandStoreSettings;
9	use App\Models\Retail\CommissionPayout;
10	use App\Models\Retail\CommissionPayoutItem;
11	use App\Services\Notifications\NotificationPublisher;
12	use Illuminate\Support\Facades\DB;
13	use Illuminate\Support\Facades\Log;
14	use Stripe\Exception\ApiConnectionException;
15	use Stripe\Exception\ApiErrorException;
16	use Stripe\Exception\RateLimitException;
17	use Stripe\StripeClient;
18	
19	// V2: Core. Processes eligible commission payouts with hybrid funding (wallet balance first, card charge for shortfall). Transfers net amount to affiliate via Stripe Connect (80/20 split).
20	class CommissionPayoutService
21	{
22	    private StripeClient $stripe;
23	
24	    private NotificationPublisher $publisher;
25	
26	    private float $platformFeePercent;
27	
28	    private int $systemHoldDays;
29	
30	    private int $minHoldDays;
31	
32	    private int $gracePeriodDays;
33	
34	    public function __construct(?StripeClient $stripe = null, ?NotificationPublisher $publisher = null)
35	    {
36	        $this->stripe = $stripe ?? new StripeClient(config('services.stripe.secret_key'));
37	        $this->publisher = $publisher ?? app(NotificationPublisher::class);
38	        $this->platformFeePercent = config('partna.store.platform_fee_percent', 3);
39	        $this->systemHoldDays = max(0, (int) config('partna.store.payout_hold_days', 7));
40	        $this->minHoldDays = (int) config('partna.store.min_payout_hold_days', 7);
41	        // Clamp to [1, 365] — values outside this range produce nonsensical void_at timestamps.
42	        $this->gracePeriodDays = max(1, min(365, (int) config('partna.store.grace_period_days', 60)));
43	    }
44	
45	    /**
46	     * Main entry point: find all eligible unpaid commissions, batch them,
47	     * and dispatch a per-payout job for each. Returns dispatch counts only —
48	     * actual results are reported per-job via Horizon.
49	     *
50	     * @return array{batches_dispatched: int, batches_created: int, batches_requeued: int}
51	     */
52	    public function processEligiblePayouts(): array
53	    {
54	        $stats = [
55	            'batches_dispatched' => 0,
56	            'batches_created' => 0,
57	            'batches_requeued' => 0,
58	        ];
59	
60	        // Re-dispatch any in-flight batches. ExecuteCommissionPayoutJob's idempotent
61	        // resume logic handles collecting/transferring states safely.
62	        // Skip wallet_currency_mismatch payouts — they cannot proceed until the brand
63	        // resolves the mismatch manually. Re-dispatching them floods Horizon with no
64	        // forward progress; the sweep picks them up again once an admin clears the code.
65	        $existingPending = CommissionPayout::query()
66	            ->whereIn('status', ['pending', 'pending_funds', 'collecting', 'transferring'])
67	            ->whereNull('processed_at')
68	            ->where('eligible_after', '<=', now())
69	            ->where(function ($q) {
70	                $q->whereNull('failure_code')
71	                    ->orWhere('failure_code', '!=', 'wallet_currency_mismatch');
72	            })
73	            ->orderBy('eligible_after')
74	            ->limit(500)
75	            ->get();
76	
77	        foreach ($existingPending as $pendingPayout) {
78	            ExecuteCommissionPayoutJob::dispatch($pendingPayout->id);
79	            $stats['batches_dispatched']++;
80	            $stats['batches_requeued']++;
81	        }
82	
83	        // Find all brands with unpaid approved orders, then apply per-brand hold days
84	        // to determine which orders have cleared their hold window.
85	        // Phase 3.5: source of truth moves from commission_movements to commerce.orders.
86	        $brandIds = Order::query()
87	            ->where('status', 'approved')
88	            ->whereNull('payout_id')
89	            ->where('refund_cents', 0)
90	            ->distinct()
91	            ->pluck('brand_professional_id');
92	
93	        // Pre-load brand store settings for hold-day lookups.
94	        $brandSettings = BrandStoreSettings::query()
95	            ->whereIn('professional_id', $brandIds)
96	            ->pluck('payout_hold_days', 'professional_id');
97	
98	        foreach ($brandIds as $brandId) {
99	            $holdDays = $this->resolveHoldDays($brandSettings[$brandId] ?? null);
100	            $cutoff = now()->utc()->subDays($holdDays);
101	
102	            $groups = Order::query()
103	                ->where('status', 'approved')
104	                ->whereNull('payout_id')
105	                ->where('refund_cents', 0)
106	                ->where('brand_professional_id', $brandId)
107	                ->where('occurred_at', '<=', $cutoff)
108	                ->select([
109	                    'brand_professional_id',
110	                    'affiliate_professional_id',
111	                    'currency_code',
112	                    DB::raw('SUM(commission_cents) as total_cents'),
113	                    DB::raw('COUNT(*) as entry_count'),
114	                ])
115	                ->groupBy('brand_professional_id', 'affiliate_professional_id', 'currency_code')
116	                ->having(DB::raw('SUM(commission_cents)'), '>', 0)
117	                ->get();
118	
119	            foreach ($groups as $group) {
120	                try {
121	                    $payout = $this->createPayoutBatch(
122	                        $group->brand_professional_id,
123	                        $group->affiliate_professional_id,
124	                        $group->currency_code,
125	                        $cutoff,
126	                    );
127	
128	                    if (! $payout) {
129	                        continue;
130	                    }
131	
132	                    $stats['batches_created']++;
133	                    ExecuteCommissionPayoutJob::dispatch($payout->id);
134	                    $stats['batches_dispatched']++;
135	                } catch (\Throwable $e) {
136	                    Log::error('Commission payout batch creation failed', [
137	                        'brand_id' => $group->brand_professional_id,
138	                        'affiliate_id' => $group->affiliate_professional_id,
139	                        'currency' => $group->currency_code,
140	                        'error' => $e instanceof ApiErrorException ? ($e->getStripeCode() ?? 'stripe_error') : get_class($e),
141	                    ]);
142	                }
143	            }
144	        }
145	
146	        return $stats;
147	    }
148	
149	    /**
150	     * Resolve the effective hold days for a brand.
151	     * Uses brand override if set, otherwise system default. Always >= system minimum.
152	     */
153	    private function resolveHoldDays(?int $brandPayoutHoldDays): int
154	    {
155	        $days = $brandPayoutHoldDays ?? $this->systemHoldDays;
156	
157	        return max($this->minHoldDays, $days);
158	    }
159	
160	    /**
161	     * Create a payout batch record and link all eligible orders.
162	     *
163	     * Phase 3.5+: reads from commerce.orders directly (not commission_movements).
164	     * Orders that are refunded after status='approved' have their status flipped to
165	     * 'partially_refunded'/'refunded', which the WHERE clause already excludes. Refunds
166	     * that arrive AFTER a payout is created are not reconciled in v1 — acceptable pre-beta;
167	     * tracked for Phase 4.
168	     */
169	    private function createPayoutBatch(
170	        string $brandId,
171	        string $affiliateId,
172	        string $currency,
173	        \DateTimeInterface $cutoff,
174	    ): ?CommissionPayout {
175	        // READ COMMITTED (PG default) — lockForUpdate() prevents a concurrent batch
176	        // from claiming the same orders between the SELECT and the payout_id stamp.
177	        return DB::transaction(function () use ($brandId, $affiliateId, $currency, $cutoff) {
178	            $orders = Order::query()
179	                ->where('status', 'approved')
180	                ->whereNull('payout_id')
181	                ->where('refund_cents', 0)
182	                ->where('brand_professional_id', $brandId)
183	                ->where('affiliate_professional_id', $affiliateId)
184	                ->where('currency_code', $currency)
185	                ->where('occurred_at', '<=', $cutoff)
186	                ->lockForUpdate()
187	                ->get();
188	
189	            if ($orders->isEmpty()) {
190	                return null;
191	            }
192	
193	            $grossCents = (int) $orders->sum('commission_cents');
194	            if ($grossCents <= 0) {
195	                return null;
196	            }
197	
198	            $platformFeeCents = (int) round($grossCents * $this->platformFeePercent / 100);
199	            $netPayoutCents = $grossCents - $platformFeeCents;
200	
201	            if ($netPayoutCents <= 0) {
202	                return null;
203	            }
204	
205	            // Per-payout grace window — 60d from creation. If the affiliate
206	            // hasn't activated Stripe Connect by then, VoidExpiredPayoutsJob
207	            // cancels this payout and clears the orders' payout_id stamps.
208	            // grace_period_days lives in config/sidest.php so ops can tune
209	            // the policy without a code release.
210	            // ledger_entry_count now counts orders included; column rename deferred to Phase 4.
211	            $payout = CommissionPayout::forceCreate([
212	                'brand_professional_id' => $brandId,
213	                'affiliate_professional_id' => $affiliateId,
214	                'status' => 'pending',
215	                'gross_commission_cents' => $grossCents,
216	                'platform_fee_cents' => $platformFeeCents,
217	                'net_payout_cents' => $netPayoutCents,
218	                'currency_code' => strtoupper($currency),
219	                'ledger_entry_count' => $orders->count(),
220	                'eligible_after' => $cutoff,
221	                'void_at' => now()->addDays($this->gracePeriodDays),
222	                'funding_source' => null,
223	            ]);
224	
225	            // Create one payout item per order; stamp orders.payout_id atomically
226	            // so the next sweep cannot double-claim these orders.
227	            foreach ($orders as $order) {
228	                CommissionPayoutItem::create([
229	                    'payout_id' => $payout->id,
230	                    'order_id' => $order->id,
231	                    'amount_cents' => $order->commission_cents,
232	                ]);
233	            }
234	
235	            Order::whereIn('id', $orders->pluck('id')->all())
236	                ->update(['payout_id' => $payout->id]);
237	
238	            return $payout;
239	        });
240	    }
241	
242	    /**
243	     * Process a single payout through the full 3-step flow with idempotent resume:
244	     *   1) Debit wallet balance (atomic with status update — crash-safe).
245	     *   2) Charge brand's card for any shortfall.
246	     *   3) Transfer net amount to affiliate via Stripe Connect.
247	     *
248	     * Each step checks the payout's current status before executing, so retries
249	     * (both Horizon automatic and admin manual) resume from where they left off
250	     * rather than restarting from scratch. This prevents double-debiting the wallet
251	     * and double-charging the brand's card.
252	     *
253	     * Return values:
254	     * - true:  completed
255	     * - null:  pending for funding/retry
256	     * - false: failed
257	     */
258	    public function processPayoutBatch(CommissionPayout $payout): ?bool
259	    {
260	        if ($payout->status === 'completed') {
261	            return true;
262	        }
263	
264	        $brand = Professional::find($payout->brand_professional_id);
265	        $affiliate = Professional::find($payout->affiliate_professional_id);
266	
267	        if (! $affiliate?->stripe_connect_account_id || $affiliate->stripe_connect_status !== 'active') {
268	            $this->markPendingFunding($payout, 'affiliate_not_connected', 'Affiliate Stripe Connect account is not active — holding for grace period');
269	
270	            return null;
271	        }
272	
273	        if (! $brand) {
274	            $this->failPayout($payout, 'brand_missing', 'Brand account was not found.');
275	
276	            return false;
277	        }
278	
279	        if (! $brand->stripe_customer_id || ! $brand->stripe_payment_method_id) {
280	            $this->markPendingFunding(
281	                $payout,
282	                'brand_payment_method_missing',
283	                'No payment method on file. Please add a card in your Stripe settings.',
284	            );
285	
286	            return null;
287	        }
288	
289	        $currencyUpper = strtoupper($payout->currency_code);
290	        $currencyLower = strtolower($currencyUpper);
291	        $amountToCollect = $payout->gross_commission_cents;
292	
293	        // Idempotency key suffix used only for PaymentIntents — retry_count is incremented
294	        // on each admin manual retry so a fresh PI is created rather than returning a
295	        // refunded/failed one from within the 24-hour idempotency TTL window.
296	        // Transfers intentionally use a stable key (no suffix) so Stripe returns the same
297	        // transfer on any retry, preventing a duplicate payout if the transfer succeeded
298	        // but the HTTP response was lost before the ID could be recorded.
299	        $retryKey = '_r'.$payout->retry_count;
300	
301	        // Step 1: Wallet debit — or resume from recorded state
302	        //
303	        // The debit and the status update are wrapped in a single DB::transaction
304	        // so a process crash between them can't leave the wallet reduced but the
305	        // payout record still showing 'pending' (which would cause a double-debit on retry).
306	        $walletDebitCents = 0;
307	        $chargeAmountCents = $amountToCollect;
308	
