542	    /**
543	     * Debit the brand's wallet balance, up to the requested amount (partial OK).
544	     * Returns the actual amount debited (0 if no balance available).
545	     *
546	     * Sets $hasCurrencyMismatch=true when the wallet has a positive balance but in a
547	     * different currency than $currencyCode — caller must treat this as a hard stop,
548	     * not a zero-balance case, to avoid silently charging the full amount to the card.
549	     */
550	    private function debitBrandManualBalancePartial(string $brandId, int $requestedCents, string $currencyCode, bool &$hasCurrencyMismatch = false): int
551	    {
552	        if ($requestedCents <= 0) {
553	            return 0;
554	        }
555	
556	        // READ COMMITTED (PG default) — lockForUpdate() on the professional row
557	        // serialises concurrent debits; no higher isolation level is required.
558	        return DB::transaction(function () use ($brandId, $requestedCents, $currencyCode, &$hasCurrencyMismatch) {
559	            $brand = Professional::query()
560	                ->whereKey($brandId)
561	                ->lockForUpdate()
562	                ->first();
563	
564	            if (! $brand) {
565	                return 0;
566	            }
567	
568	            $balance = max(0, (int) ($brand->stripe_manual_balance_cents ?? 0));
569	            $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
570	
571	            if ($walletCurrency !== strtoupper($currencyCode)) {
572	                // Only flag as a mismatch when there's actual balance in the wrong currency.
573	                // An empty wallet with any currency is just "no funds" — not a mismatch.
574	                if ($balance > 0) {
575	                    $hasCurrencyMismatch = true;
576	                }
577	
578	                return 0;
579	            }
580	
581	            if ($balance <= 0) {
582	                return 0;
583	            }
584	
585	            $debit = min($balance, $requestedCents);
586	            $brand->stripe_manual_balance_cents = $balance - $debit;
587	            $brand->save();
588	
589	            return $debit;
590	        });
591	    }
592	
593	    public function creditBrandManualBalance(string $brandId, int $amountCents, string $currencyCode): void
594	    {
595	        if ($amountCents <= 0) {
596	            return;
597	        }
598	
599	        // READ COMMITTED (PG default) — lockForUpdate() serialises concurrent credits.
600	        DB::transaction(function () use ($brandId, $amountCents, $currencyCode) {
601	            $brand = Professional::query()
602	                ->whereKey($brandId)
603	                ->lockForUpdate()
604	                ->first();
605	
606	            if (! $brand) {
607	                return;
608	            }
609	
610	            $balance = (int) ($brand->stripe_manual_balance_cents ?? 0);
611	            $brand->stripe_manual_balance_cents = $balance + $amountCents;
612	            $brand->stripe_manual_balance_currency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
613	            $brand->save();
614	        });
615	    }
616	
617	    private function extractLatestChargeId(object $paymentIntent): ?string
618	    {
619	        if (is_string($paymentIntent->latest_charge ?? null) && $paymentIntent->latest_charge !== '') {
620	            return $paymentIntent->latest_charge;
621	        }
622	
623	        if (is_object($paymentIntent->latest_charge ?? null) && is_string($paymentIntent->latest_charge->id ?? null)) {
624	            return $paymentIntent->latest_charge->id;
625	        }
626	
627	        if (is_object($paymentIntent->charges ?? null) && is_array($paymentIntent->charges->data ?? null)) {
628	            foreach ($paymentIntent->charges->data as $charge) {
629	                if (is_object($charge) && is_string($charge->id ?? null) && $charge->id !== '') {
630	                    return $charge->id;
631	                }
632	            }
633	        }
634	
635	        return null;
636	    }
637	
638	    private function markPendingFunding(CommissionPayout $payout, string $code, string $reason): void
639	    {
640	        $payout->forceFill([
641	            'status' => 'pending_funds',
642	            'failure_code' => $code,
643	            'failure_reason' => $reason,
644	            'processed_at' => null,
645	            // Reset expiry each time we park the payout — without this, the void clock
646	            // counts from original creation while the payout loops in pending_funds,
647	            // causing VoidExpiredPayoutsJob to silently erase the affiliate's commission.
648	            'void_at' => now()->addDays($this->gracePeriodDays),
649	        ])->save();
650	
651	        Log::notice('Commission payout pending funding', [
652	            'payout_id' => $payout->id,
653	            'code' => $code,
654	            'reason' => $reason,
655	        ]);
656	    }
657	
658	    private function failPayout(CommissionPayout $payout, string $code, string $reason): void
659	    {
660	        $payout->forceFill([
661	            'status' => 'failed',
662	            'failure_code' => $code,
663	            'failure_reason' => $reason,
664	        ])->save();
665	
666	        Log::warning('Commission payout failed', [
667	            'payout_id' => $payout->id,
668	            'code' => $code,
669	            'reason' => $reason,
670	        ]);
671	    }
672	
673	    /**
674	     * Manually retry a stuck payout batch (admin endpoint).
675	     *
676	     * Increments retry_count so a fresh Stripe idempotency key is used —
677	     * prevents Stripe returning a refunded/failed PI from within the 24h TTL window.
678	     *
679	     * Blocked for transfer_failed_refund_needed: the auto-refund itself failed, so
680	     * the brand may still be charged. Manual verification is required before retrying.
681	     *
682	     * Runs synchronously so the admin sees the result immediately.
683	     */
684	    public function retryPayout(CommissionPayout $payout): bool
685	    {
686	        if (! in_array($payout->status, ['failed', 'pending', 'pending_funds'], true)) {
687	            return false;
688	        }
689	
690	        // Auto-refund failed — manual verification required before retrying to avoid double-charging.
691	        if ($payout->failure_code === 'transfer_failed_refund_needed') {
692	            return false;
693	        }
694	
695	        // If the wallet was already debited in a previous run, resume from 'collecting'
696	        // so processPayoutBatch() enters its idempotent resume branch and skips
697	        // re-debiting. Resetting to 'pending' would bypass that branch and double-debit.
698	        $resumeStatus = ((int) ($payout->wallet_debit_cents ?? 0)) > 0 ? 'collecting' : 'pending';
699	
700	        $payout->forceFill([
701	            'status' => $resumeStatus,
702	            'failure_code' => null,
703	            'failure_reason' => null,
704	            'needs_manual_refund' => false,
705	            'retry_count' => ($payout->retry_count ?? 0) + 1,
706	        ])->save();
707	
708	        return $this->processPayoutBatch($payout) === true;
709	    }
710	
711	    private function formatMoney(int $cents, string $currencyCode): string
712	    {
713	        $prefix = match (strtoupper($currencyCode)) {
714	            'USD' => '$',
715	            'GBP' => '£',
716	            'EUR' => '€',
717	            'AUD' => 'A$',
718	            default => strtoupper($currencyCode).' ',
719	        };
720	
721	        return $prefix.number_format($cents / 100, 2, '.', ',');
722	    }
723	
724	    /**
725	     * Get payout summary for a professional (as brand or affiliate).
726	     */
727	    public function getPayoutSummary(Professional $professional): array
728	    {
729	        $asBrand = CommissionPayout::query()
730	            ->where('brand_professional_id', $professional->id)
731	            ->selectRaw('status, COUNT(*) as count, SUM(gross_commission_cents) as total_cents')
732	            ->groupBy('status')
733	            ->get()
734	            ->keyBy('status');
735	
736	        $asAffiliate = CommissionPayout::query()
737	            ->where('affiliate_professional_id', $professional->id)
738	            ->selectRaw('status, COUNT(*) as count, SUM(net_payout_cents) as total_cents')
739	            ->groupBy('status')
740	            ->get()
741	            ->keyBy('status');
742	
743	        return [
744	            'as_brand' => $asBrand,
745	            'as_affiliate' => $asAffiliate,
746	        ];
747	    }
748	}
