195	/**
196	 * Build a Mockery StripeClient mock wired with per-service sub-mocks.
197	 * StripeClient::__get delegates to getService(), so we mock getService() —
198	 * that is the actual method Mockery intercepts when $stripe->paymentIntents is accessed.
199	 */
200	function payoutSvc_makeStripe(array $services = []): StripeClient
201	{
202	    $piMock = $services['pi'] ?? Mockery::mock();
203	    $transferMock = $services['transfer'] ?? Mockery::mock();
204	    $refundMock = $services['refund'] ?? Mockery::mock();
205	
206	    $stripe = Mockery::mock(StripeClient::class);
207	    $stripe->shouldReceive('getService')->with('paymentIntents')->andReturn($piMock);
208	    $stripe->shouldReceive('getService')->with('transfers')->andReturn($transferMock);
209	    $stripe->shouldReceive('getService')->with('refunds')->andReturn($refundMock);
210	
211	    return $stripe;
212	}
